  <style>
    :root {
      --primary: #2563eb;
    }
    * {
      box-sizing: border-box;
    }
    body {
      margin: 0;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background-color: #f3f4f6;
      color: #111827;
    }
    .page {
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: flex-start;
      padding: 32px 16px;
    }
    .card {
      width: 100%;
      max-width: 960px;
      background-color: #ffffff;
      border-radius: 16px;
      box-shadow: 0 18px 45px rgba(15, 23, 42, 0.15);
      padding: 24px 28px;
    }
    .card-header {
      margin-bottom: 24px;
    }
    .card-title {
      margin: 0 0 8px;
      font-size: 1.9rem;
      font-weight: 600;
    }
    form {
      display: flex;
      flex-wrap: wrap;
      gap: 20px;
    }
    .field {
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    label {
      font-size: 0.9rem;
      color: #374151;
    }
    input, select, textarea {
      width: 100%;
      padding: 9px 11px;
      border-radius: 10px;
      border: 1px solid #d1d5db;
      font-size: 0.95rem;
      outline: none;
    }
    input:focus, select:focus, textarea:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 1px var(--primary);
    }
    textarea {
      min-height: 120px;
      resize: vertical;
    }
    .actions {
      margin-top: 8px;
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }
    .btn-primary, .btn-secondary {
      border-radius: 999px;
      border: none;
      padding: 9px 20px;
      font-size: 0.95rem;
      cursor: pointer;
      transition: background-color 0.18s ease, color 0.18s ease, transform 0.12s ease;
    }
    .btn-primary {
      background-color: var(--primary);
      color: #ffffff;
    }
    .btn-secondary {
      background-color: #ffffff;
      color: #374151;
      border: 1px solid #d1d5db;
    }
    .btn-primary:hover {
      background-color: #1d4ed8;
      transform: translateY(-1px);
    }
    .btn-secondary:hover {
      background-color: #f9fafb;
      transform: translateY(-1px);
    }
    @media (max-width: 640px) {
      .card {
        padding: 20px 16px;
      }
    }
    @media (min-width: 641px) and (max-width: 1023px) {
      form {
        flex-wrap: wrap;
      }
      .field {
        width: 48%;
      }
    }
  </style>
</head>
